  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'ساعة حائط تتأخر بمقدار 5 دقائق كل ساعة. إذا تم ضبطها عند الساعة 12 ظهراً، فكم ستكون القراءة الصحيحة عندما تشير الساعة لـ 3:45 عصراً؟', '["الساعة 3:30","الساعة 4:15","الساعة 4:00 عصراً","الساعة 3:45"]'::jsonb, 2, 20, 195, 'multi', 'في كل ساعة حقيقية 60 دقيقة تقرأ الساعة 55 دقيقة. 3:45 تعادل 225 دقيقة قراءة = 4 ساعات حقيقية (4:00).', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'مسائل الوقت والنسب المنطقية', 'LOG-0046', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كان لدى أحمد 3 إخوة وكل أخ لديه أخت واحدة، فكم عدد الأبناء والبنات الإجمالي في هذه العائلة؟', '["6 أبناء","7 أبناء","8 أبناء","5 أبناء وبنات (4 ذكور وبنت واحدة)"]'::jsonb, 3, 20, 196, 'multi', 'أحمد + 3 إخوة = 4 ذكور، ولهم جميعاً نفس الأخت الواحدة = 5 أبناء وبنات.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'أحجيات الألغاز العائلية', 'LOG-0047', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا سار شخص باتجاه الشمال 4 كم، ثم اتجه شرقاً وسار 3 كم، فكم يبعد عن نقطة البداية خطاً مستقيماً؟', '["5 كم","7 كم","1 كم","12 كم"]'::jsonb, 0, 20, 197, 'multi', 'باستخدام مبرهنة فيثاغورس الجذر التربيعي لـ (4² + 3²) = √(16+9) = √25 = 5 كم.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'الهندسة وحساب المسافات المنطقية', 'LOG-0048', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كانت النملة تتسلق جداراً ارتفاعه 10 أمتار، تتسلق 3 أمتار بالنهار وتنزلق مترين بالليل، ففي كم يوماً تصل لأعلى الجدار؟', '["10 أيام","في 8 أيام","5 أيام","9 أيام"]'::jsonb, 1, 20, 198, 'multi', 'في اليوم الأول تصل لـ 1م الصافي. في نهاية اليوم 7 تصل لـ 7م. في نهار اليوم 8 تتسلق 3م فتصل 10م وتخرج قبل انزلاق الليل.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'أحجيات الحركة والمسافات الكلاسيكية', 'LOG-0049', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كان مجموع عمري أب وابنه 45 سنة، وكان عمر الأب يزيد عن عمر ابنه بـ 35 سنة، فكم عمر الابن؟', '["10 سنوات","2.5 سنة","5 سنوات","7 سنوات"]'::jsonb, 2, 20, 199, 'multi', 'س (الأب) + ص (الابن) = 45، س - ص = 35. بطرح المعادلتين 2ص = 10 إذاً ص = 5 سنوات (والأب 40).', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'المعادلات الكلامية الذكية', 'LOG-0050', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كانت 5 آلات تستغرق 5 دقائق لصنع 5 قطعة، فكم دقيقة تستغرق 100 آلة لصنع 100 قطعة؟', '["100 دقيقة","50 دقيقة","1 دقيقة","5 دقائق"]'::jsonb, 3, 20, 200, 'multi', 'كل آلة واحدة تستغرق 5 دقائق لصنع قطعة واحدة. بالتالي 100 آلة تعمل بالتوازي تصنع 100 قطعة في 5 دقائق أيضاً.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'مسائل التناسب والزمن والعمل', 'LOG-0051', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كان سعر القلم والدفتر معاً 11 ريالاً، وكان سعر الدفتر يزيد عن القلم بـ 10 ريالات، فكم سعر القلم؟', '["0.5 ريال (نصف ريال)","ريال واحد","2 ريال","1.5 ريال"]'::jsonb, 0, 20, 201, 'multi', 'القلم س والدفتر س+10. س + س + 10 = 11 -> 2س = 1 -> س = 0.5 ريال (والدفتر 10.5 ريال).', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'اختبار التفكير السريع والمنطق الذهني', 'LOG-0052', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'طائرة تطير بين مدينتين، إذا قطعت المسافة في ذهابها بـ 80 دقيقة، واستغرقت في العودة ساعة و20 دقيقة، فهناك اختلاف في السرعة.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 202, 'multi', 'ساعة و20 دقيقة هي نفسها 80 دقيقة بال تماماً، بالتالي الزمن متطابق والسرعة متطابقة.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'القياس الزمني الذهني', 'LOG-0053', true, 2),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كان لديك 8 كرات متطابقة بالكامل للشكل، وواحدة منها أثقل قليلاً، فما أقل عدد مرات ميزان بكفتين لمعرفة الكرة الثقيلة حتماً؟', '["3 مرات","4 مرات","مرتان فقط","مرة واحدة"]'::jsonb, 2, 20, 203, 'multi', 'نقسم الكرات إلى 3 و 3 و 2. الوزنة الأولى تقارن 3 ضد 3 فتحدد المجموعة الثقيلة، ثم الوزنة الثانية تحسمها.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'أحجيات الوزن والموازين التكتيكية', 'LOG-0054', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا تضاعف عدد البكتيريا في كوب كل دقيقة، وتمتلئ الكوب بالكامل بعد 60 دقيقة، فمتى تكون الكوب ممتلئة لنصفها؟', '["بعد 30 دقيقة","بعد 15 دقيقة","بعد 45 دقيقة","بعد 59 دقيقة"]'::jsonb, 3, 20, 204, 'multi', 'بما أن عدد البكتيريا يتضاعف كل دقيقة، ففي الدقيقة 59 كانت النصف، وفي الدقيقة 60 تضاعفت لتصبح الكوب كاملة.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'النمو الأسي والمنطق العكسي', 'LOG-0055', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كان خالد خلف محمد، وحسام أمام محمد، فمن هو الشخص الموجود في الوسط بين الثلاثة؟', '["محمد","خالد","حسام","لا يمكن التحديد"]'::jsonb, 0, 20, 205, 'multi', 'الترتيب من الأمام للخلف: حسام ثم محمد ثم خالد، بالتالي محمد يقع في الوسط.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'الترتيب مكاني وبصري', 'LOG-0056', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كان حاصل ضرب عدديين صحيحين هو 12، ومجموعهما 7، فما هما العددان؟', '["2 و 6","3 و 4","1 و 12","5 و 2"]'::jsonb, 1, 20, 206, 'multi', '3 × 4 = 12 و 3 + 4 = 7.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'المعادلات الرقمية الذهنية السريعة', 'LOG-0057', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'قطار يتجه نحو الشرق بسرعة 100 كم/ساعة والرياح تهب نحو الغرب، فإلى أين يتجه دخان القطار الكهربائي؟', '["نحو الغرب","نحو الشرق","القطار الكهربائي لا يخرج دخاناً","نحو الشمال"]'::jsonb, 2, 20, 207, 'multi', 'لغز الانتباه للتفاصيل: القطارات الكهربائية لا تنتج دخاناً.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'ألغاز الدقة والتركيز الذهني', 'LOG-0058', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا كان لجميع الكلاب أربعة أرجل، وجميع القطط لها أربعة أرجل، فإن جميع الكلاب قطط.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 208, 'multi', 'نتيجة خاطئة تماماً منطقياً لعدم وجود علاقة احتواء بين المجموعتين.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'المنطق الصوري والمجموعات', 'LOG-0059', true, 2),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'إذا تجاوزت المتسابق صاحب المركز الثاني في سباق جري، فما هو مركزك الحالي في السباق؟', '["المركز الثاني","المركز الأول","المركز الثالث","المركز أخير"]'::jsonb, 0, 20, 209, 'multi', 'عندما تتجاوز صاحب المركز الثاني فأنت تأخذ مكانه وتصبح في المركز الثاني وهو يصبح في الثالث.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'ألغاز التفكير المباشر والتحدي', 'LOG-0060', true, 1),
  ('37ba3999-e25b-4d8a-a47d-f73920ddecac', 'أب عمره أربعة أضعاف عمر ابنه. بعد 20 سنة، يصبح عمر الأب ضعفي عمر ابنه. كم عمر الابن الآن؟', '["5 سنوات","10 سنوات","15 سنة","20 سنة"]'::jsonb, 1, 20, 210, 'multi', 'الآن: الابن س والأب 4س. بعد 20 سنة: 4س + 20 = 2(س + 20) -> 4س + 20 = 2س + 40 -> 2س = 20 -> س = 10 سنوات.', 'medium', 'ألغاز واستنتاج', '{"منطق وذكاء","ألغاز واستنتاج"}'::text[], 'مسائل الأعمار المنطقية', 'LOG-0061', true, 1),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'ما اسم المغالطة المنطقية التي تقوم على مهاجمة شخص الخصم وصفاته بدلاً من مناقشة حُجته ورأيه؟', '["مغالطة رجل القش","مغالطة المنحدر الزلق","مغالطة الشخصنة (Ad Hominem)","مغالطة الاحتكام للكثرة"]'::jsonb, 2, 20, 211, 'multi', 'تعتمد على الطعن الذاتي بالشخص لإبطال حدمته دون دليل موضوعي.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'كتاب المغالطات المنطقية - عادل مصطفى', 'LOG-0062', true, 1),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'مغالطة رجل القش (Straw Man) تقوم على تشويه حجة الخصم وتبسيطها وتضعيفها ثم الهجوم على هذا التشويه بدلاً من الحجة الأصلية.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 212, 'multi', 'أسلوب شائع في المناظرات والجدل غير الموضوعي.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'المغالطات المنطقية - عادل مصطفى', 'LOG-0063', true, 2),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'ما اسم المغالطة التي تنص على أن الشيء صحيح لمجرد أن أغلبية الناس أو الجمهور يؤمنون بصحته؟', '["مغالطة الاحتكام إلى الأغلبية / الكثرة (Ad Populum)","مغالطة السلطة","مغالطة الجهل","مغالطة المنحدر الزلق"]'::jsonb, 0, 20, 213, 'multi', 'الكثرة لا تعتبر إثباتاً للصح والخطأ في المنهج العلمي والمنطقي.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Logic and Critical Thinking Guide', 'LOG-0064', true, 1),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'ما اسم المغالطة التي تفترض أن وقوع حدث ما سيؤدي حتماً بسلسلة أحداث كارثية دون وجود أدلة منطقية ترابطية؟', '["مغالطة العاطفة","مغالطة المنحدر الزلق (Slippery Slope)","مغالطة التوسل بالجهل","مغالطة التعميم السريع"]'::jsonb, 1, 20, 214, 'multi', 'الربط التعسفي بين الخطوة الأولى والنتائج المهولة.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Critical Thinking Manual', 'LOG-0065', true, 1),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'مغالطة التوسل بالجهل (Argument from Ignorance) تعتبر أن الشيء صحيح لمجرد أنه لم يثبت بطلانه بعد.', '["صح","خطأ"]'::jsonb, 0, 20, 215, 'boolean', 'عدم وجود الدليل على عدم الشيء ليس دليلاً على وجوده.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'The Art of Reasoning', 'LOG-0066', true, 1),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'ما اسم المغالطة التي تقوم على تقديم خيارين اثنين فقط للحل أو الموقف مع وجود خيارات متعددة أخرى؟', '["مغالطة السؤال المركب","مغالطة التعميم","مغالطة السبب الزائف","مغالطة المعضلة الزائفة / إما أو (False Dilemma)"]'::jsonb, 3, 20, 216, 'multi', 'تضييق الخيارات عمداً على الطرف الآخر لإجباره على اتخاذ موقف معين.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Critical Thinking & Logic', 'LOG-0067', true, 1),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'ما اسم المغالطة التي تنشأ من الاستدلال بـ نتيجة من خلال أخذ عينة صغيرة غير كافية وإطلاق حكم عام؟', '["مغالطة التعميم المتسرع (Hasty Generalization)","مغالطة العاطفة","مغالطة المنحدر","مغالطة الشخصنة"]'::jsonb, 0, 20, 217, 'multi', 'الحكم على مجموعة كاملة بناءً على تجربة فردية أو عينة ضئيلة.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Introduction to Logic - Copi', 'LOG-0068', true, 1),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'مغالطة السبب الزائف (Post Hoc) تفترض أن حدوث حدث بعد حدث آخر يعني بالضرورة أن الأول هو سبب الثاني.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 218, 'multi', 'مجرد التتابع الزمني لا يقتضي العلية والسببية.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Logic & Post Hoc Ergo Propter Hoc', 'LOG-0069', true, 2),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'ما اسم المغالطة التي تستخدم إثارة مشاعر الشفقة أو الخوف بدلاً من تقديم أدلة وحجج منطقية؟', '["مغالطة الشخصنة","مغالطة المنحدر","مغالطة التوسل بالعاطفة (Appeal to Emotion)","مغالطة المعضلة"]'::jsonb, 2, 20, 219, 'multi', 'استغلال العاطفة والتأثير النفسي لإقناع السامع بدلاً من العقل.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Attacking Faulty Reasoning', 'LOG-0070', true, 1),
  ('e8c9cb8a-8f2f-43da-ae62-feab2f1812fa', 'ما اسم المغالطة التي تنطوي على تقديم الاستدلال الدائري بحيث تكون النتيجة مأخوذة ومفترضة داخل المقدمات نفسها؟', '["مغالطة السؤال الموجه","مغالطة رجل القش","مغالطة المنحدر","مغالطة المصادرة على المطلوب (Begging the Question)"]'::jsonb, 3, 20, 220, 'multi', 'الدوران حول النفس دون تقديم برهان حقيقي جديد.', 'medium', 'تفكير ناقد ومغالطات', '{"منطق وذكاء","تفكير ناقد ومغالطات"}'::text[], 'Stanford Encyclopedia - Fallacies', 'LOG-0071', true, 1),
