  ('f63e1694-a91e-42b1-a5d8-f6f1e20a9152', 'ما اسم التحويل الهندسي الذي ينقل جميع نقاط الشكل مسافة متساوية في اتجاه معين دون تدويره؟', '["الإزاحة / الانسحاب (Translation)","الدوران","الانعكاس","التكبير"]'::jsonb, 0, 20, 273, 'multi', 'حافظ على القياسات والاتجاهات بالكامل.', 'medium', 'روابط مكانية وهندسية', '{"منطق وذكاء","روابط مكانية وهندسية"}'::text[], 'Transformational Geometry', 'LOG-0124', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'سار قطار بسرعة 60 كم/ساعة لمدة 3 ساعات. ما هي المسافة الإجمالية التي قطعها القطار؟', '["120 كم","180 كم","200 كم","240 كم"]'::jsonb, 1, 20, 274, 'multi', 'المسافة = السرعة × الزمن = 60 × 3 = 180 كم.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الحركة والسرعة الحسابية', 'LOG-0125', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا كانت النسبة بين ولد وبنت في صف مدرسي هي 3 : 2، وكان إجمالي عدد الطلاب 30 طالباً، فكم عدد الأولاد؟', '["12 ولداً","15 ولداً","18 ولداً","20 ولداً"]'::jsonb, 2, 20, 275, 'multi', 'عدد الأجزاء = 3 + 2 = 5 أجزاء. قيمة الجزء = 30 ÷ 5 = 6 طلاب. الأولاد = 3 × 6 = 18 ولداً.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل النسب والتناسب', 'LOG-0126', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا انخفض سعر سلعة بنسبة 20%، ثم ارتفع السعر الجديد بنسبة 20%، فإن السعر النهائي يرجع لسعره الأصلي.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 276, 'multi', 'السعر النهائي يصبح 96% من السعر الأصلي (نقص بـ 4%) لأن الارتفاع تم على القيمة المنخفضة.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'حساب النسبة المئوية المركبة', 'LOG-0127', true, 2),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'تاجر اشترى بضعة بـ 80 ريالاً وباعها بـ 100 ريال. ما هي نسبة ربحه المئوية مقارنة بسعر الشراء؟', '["25%","20%","15%","30%"]'::jsonb, 0, 20, 277, 'multi', 'مقدار الربح = 100 - 80 = 20 ريالاً. نسبة الربح = (20 ÷ 80) × 100 = 25%.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الربح والخسارة والنسبة', 'LOG-0128', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا كان 4 عمال يستغرقون 6 أيام لبناء جدار، فكم يوماً يستغرق 8 عمال لبناء نفس الجدار بنفس الكفاءة؟', '["12 يوماً","3 أيام","4 أيام","2 يومان"]'::jsonb, 1, 20, 278, 'multi', 'تناسب عكسي: 4 × 6 = 24 عمل كلي. 24 ÷ 8 عمال = 3 أيام.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'التناسب العكسي ومسائل العمل', 'LOG-0129', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'خزان ماء سعت الإجمالية 120 ليتراً، يمتلئ بإنبوب يضخ 30 ليتراً بالساعة، ويتسرب منه 10 ليترات بالساعة. كم ساعة يلزمه ليمتلئ بالكامل؟', '["4 ساعات","12 ساعة","6 ساعات","3 ساعات"]'::jsonb, 2, 20, 279, 'multi', 'معدل ملء الخزان الصافي = 30 - 10 = 20 ليتراً بالساعة. الوقت = 120 ÷ 20 = 6 ساعات.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل المعدل التدفيقي والزمن', 'LOG-0130', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا كان متوسط درجات 4 طلاب في اختبار هو 85. إذا أضيف طالب خامس حصل على 95، فما هو المتوسط الجديد للطلاب الخمسة؟', '["88","90","86","87"]'::jsonb, 3, 20, 280, 'multi', 'مجموع درجات 4 طلاب = 4 × 85 = 340. المجموع الجديد = 340 + 95 = 435. المتوسط الجديد = 435 ÷ 5 = 87.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل المتوسط الحسابي والتعديلات', 'LOG-0131', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'ثلاثة أعداد متتالية مجموعها يساوي 45. ما هو العدد الأوسط بينها؟', '["15","14","16","15.5"]'::jsonb, 0, 20, 281, 'multi', 'العدد الأوسط في أعداد متتالية فردية العدد يساوي المتوسط = 45 ÷ 3 = 15. الأعداد هي (14، 15، 16).', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الأعداد الحسابية المتتالية', 'LOG-0132', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا كانت مساحة مستطيل 48 سم²، وطوله يزيد عن عرضه بـ 2 سم، فما هو طول المستطيل؟', '["6 سم","8 سم","12 سم","10 سم"]'::jsonb, 1, 20, 282, 'multi', 'الطول س والعرض س-2. س(س-2) = 48 -> 8 × 6 = 48. بالتالي الطول = 8 سم والعرض = 6 سم.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'الهندسة والمعادلات الكلامية', 'LOG-0133', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا قطع رجل مسافة بسباق بساعة وربع (75 دقيقة) وتوقف للاستراحة 15 دقيقة، فإن زمن الحركة الصافي ساعة واحدة.', '["صح","خطأ"]'::jsonb, 0, 20, 283, 'boolean', 'الزمن الصافي = 75 - 15 = 60 دقيقة = ساعة واحدة.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'تحليل الأوقات والحركة', 'LOG-0134', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا كان عمر فهد الآن ثلاثة أضعاف عمر سعد، وبعد 5 سنوات يصبح مجموع عمريهما 50 سنة، فكم عمر سعد الآن؟', '["8 سنوات","12 سنة","15 سنة","10 سنوات"]'::jsonb, 3, 20, 284, 'multi', 'الآن: سعد س، فهد 3س. بعد 5 سنوات: (س+5) + (3س+5) = 50 -> 4س + 10 = 50 -> 4س = 40 -> س = 10 سنوات.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الأعمار والتناسب الكلامي', 'LOG-0135', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'مدرسة بها 400 طالب، 60% منهم أولاد. كم عدد البنات في هذه المدرسة؟', '["160 بنتاً","240 بنتاً","200 بنت","180 بنتاً"]'::jsonb, 0, 20, 285, 'multi', 'نسبة البنات = 100% - 60% = 40%. عدد البنات = 400 × 0.40 = 160 بنتاً.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'حساب النسبة المئوية المباشرة', 'LOG-0136', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا كانت ساعة تدق مرة واحدة عند الساعة 1، ومرتين عند الساعة 2 وهكذا.. فكم دقة تدقها بين الساعة 1 والساعة 4 ظهراً شمولاً؟', '["4 دقات","10 دقات","8 دقات","12 دقة"]'::jsonb, 1, 20, 286, 'multi', 'الدقات = 1 + 2 + 3 + 4 = 10 دقات.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'المجموع المتسلسل البسيط', 'LOG-0137', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'سيارتان تتحركان من نفس النقطة باتجاهين متعاكسين، الأولى بسرعة 80 كم/س والثانية بسرعة 70 كم/س. كم تكون المسافة بينهما بعد ساعتين؟', '["150 كم","280 كم","300 كم","200 كم"]'::jsonb, 2, 20, 287, 'multi', 'مجموع سرعتي الابتعاد = 80 + 70 = 150 كم/س. المسافة بعد ساعتين = 150 × 2 = 300 كم.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الحركة في اتجاهين متعاكسين', 'LOG-0138', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا تحركت سيارتان في نفس الاتجاه، الأولى بسرعة 90 كم/س والثانية بسرعة 70 كم/س، فإن مسافة المباعدة تزداد بـ 20 كم كل ساعة.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 288, 'multi', 'فرق السرعتين في نفس الاتجاه = 90 - 70 = 20 كم/ساعة.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'سرعة الابتعاد النسبية', 'LOG-0139', true, 2),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'اشترى شخص جهازا بـ 1200 ريال وحصل على خصم 15%. كم دفع الشخص فعلياً لشراء الجهاز؟', '["1020 ريالا","1000 ريال","1050 ريالا","1100 ريال"]'::jsonb, 0, 20, 289, 'multi', 'قيمة الخصم = 1200 × 0.15 = 180 ريالا. المبلغ المدفوع = 1200 - 180 = 1020 ريالا.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الخصم والتخفيضات المالية', 'LOG-0140', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'ما هي نسبة المساحة بين مربع طول ضلعه 2 سم ومربع آخر طول ضلعه 4 سم؟', '["1 : 2","1 : 4","1 : 8","1 : 16"]'::jsonb, 1, 20, 290, 'multi', 'مساحة الأول = 4 سم²، مساحة الثاني = 16 سم². النسبة = 4 : 16 = 1 : 4.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'نسب المساحات والمجسمات', 'LOG-0141', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا كانت تكلفة طباعة 500 ورقة هي 25 ريالاً، فكم تكلفة طباعة 1500 ورقة بنفس المعدل؟', '["50 ريالاً","100 ريال","75 ريالاً","60 ريالاً"]'::jsonb, 2, 20, 291, 'multi', '1500 ورقة هي 3 أضعاف الـ 500 ورقة، بالتالي التكلفة = 25 × 3 = 75 ريالاً.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'التناسب الطردي المباشر', 'LOG-0142', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'إذا ضاعفت نصف قطر دائرة، فإن مساحة الدائرة تزيد بمقدار ضعفين فقط.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 292, 'multi', 'المساحة تزداد بأربعة أضعاف (2²) لأن قانون المساحة يحوي r².', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'التناسب الهندسي المربع', 'LOG-0143', true, 2),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'صندوق يحتوي على كرة حمراء وكرة خضراء وكرة زرقاء. إذا سحبت كرتان معاً عشوائياً، فما احتمال ألا تكون الكرة الحمراء بينهما؟', '["1/3","2/3","1/2","1/6"]'::jsonb, 0, 20, 293, 'multi', 'عدد طرق سحب كرتين من 3 هو 3 طرق. النتيجة الوحيدة لعدم وجود الحمراء هي سحب (خضراء وزرقاء) أي طريقة واحدة = 1/3.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل الاحتمال والتجميع الكلامي', 'LOG-0144', true, 1),
  ('6ac25264-229d-4a6f-a2a9-5ab2f689901b', 'حافلة ركبها 20 شخصاً في المحطة الأولى. في المحطة الثانية نزل نصفهم وركب 5 جدد. كم شخصاً بالحافلة الآن؟', '["10 أشخاص","15 شخصاً","25 شخصاً","20 شخصاً"]'::jsonb, 1, 20, 294, 'multi', '20 - 10 (النصف) = 10 + 5 جدد = 15 شخصاً.', 'medium', 'مسائل كلامية وتحليل', '{"منطق وذكاء","مسائل كلامية وتحليل"}'::text[], 'مسائل التتبع الحسابي البسيط', 'LOG-0145', true, 1),
  ('11c8db87-305e-478d-a9df-210dd5647856', 'إذا كانت المقدمة الكبرى: ''جميع العلماء معنيون بالبحث العلمي''، والمقدمة الصغرى: ''أحمد عالم''، فما هي النتيجة الصحيحة؟', '["أحمد ليس عالماً","البحث العلمي يختص بأحمد فقط","أحمد معني بالبحث العلمي","جميع الباحثين أحمد"]'::jsonb, 2, 20, 295, 'multi', 'استنتاج قياسي صحبح ومباشر ينقل الحكم من العام إلى الخاص.', 'medium', 'قياس وافتراضات', '{"منطق وذكاء","قياس وافتراضات"}'::text[], 'قواعد القياس المنطقي الأرسطي', 'LOG-0146', true, 1),
  ('11c8db87-305e-478d-a9df-210dd5647856', 'إذا كانت المقدمة الكبرى: ''لا أحد من البخلاء محب للخير''، والمقدمة الصغرى: ''خالد بخيل''، فإن النتيجة هي ''خالد ليس محباً للخير''.', '["عبارة خاطئة بالكامل","عبارة صحيحة تماماً","عبارة صحيحة جزئياً","عبارة غير مؤكدة"]'::jsonb, 0, 20, 296, 'multi', 'قياس منطقي سالبة مقدمته الكبرى وتنتج سالبة سارية.', 'medium', 'قياس وافتراضات', '{"منطق وذكاء","قياس وافتراضات"}'::text[], 'قواعد القياس السالب', 'LOG-0147', true, 2),
  ('11c8db87-305e-478d-a9df-210dd5647856', 'ما الافتراض الكامن والضروري لصحة العبارة الترويجية التالية: ''اشترِ عصير الفواكه الطبيعي لتعزز صحتك''؟', '["أن عصير الفواكه الطبيعي يحتوي على عناصر مفيدة للصحة","أن جميع أنواع العصير ضارة","أن الشراء يجعلك غنياً","أن عصير الفواكه رخيص الثمن"]'::jsonb, 0, 20, 297, 'multi', 'العبارة تفترض ضمنياً ارتباط عصير الفاكهة الطبيعي بالفائدة الصحية لتحفيز الشراء.', 'medium', 'قياس وافتراضات', '{"منطق وذكاء","قياس وافتراضات"}'::text[], 'تحليل الافتراضات الضمنية - التفكير الناقد', 'LOG-0148', true, 1),
  ('11c8db87-305e-478d-a9df-210dd5647856', 'إذا كانت الجملة: ''جميع الطيور لها أجنحة، والنعامة طائر''، فما الاستنتاج المنطقي السليم؟', '["النعامة تطير حتماً","النعامة لها أجنحة","جميع الكائنات لها أجنحة","لا يوجد طيور بلا أجنحة"]'::jsonb, 1, 20, 298, 'multi', 'الاستنتاج يقتصر حتماً على المعطيات: النعامة طائر بالتالي لها أجنحة.', 'medium', 'قياس وافتراضات', '{"منطق وذكاء","قياس وافتراضات"}'::text[], 'المنطق الصوري المباشر', 'LOG-0149', true, 1),
  ('11c8db87-305e-478d-a9df-210dd5647856', 'إذا كانت النتيجة لا تنبع حتماً ومباشرة من المقدمات المنطقية المعطاة، فإن القياس يعتبر غير صحيح صوريًا.', '["صح","خطأ"]'::jsonb, 0, 20, 299, 'boolean', 'شرط الصحة الصورية (Validity) في علم المنطق.', 'medium', 'قياس وافتراضات', '{"منطق وذكاء","قياس وافتراضات"}'::text[], 'Formal Logic Standards', 'LOG-0150', true, 1),
